#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const int CAP = 5;
    long long items[CAP];
    int head = 0;      // index of front element
    int count = 0;     // number of elements in queue

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (arg[0] == 'E' && isdigit((unsigned char)arg[1])) {
            // ENQ command: E<number>
            char *endptr;
            long long val = strtoll(arg + 1, &endptr, 10);
            if (*endptr != '\0') {
                puts("ERR");
                continue;
            }
            if (count == CAP) {
                puts("FULL");
                continue;
            }
            items[(head + count) % CAP] = val;
            ++count;
            printf("ENQ %lld\n", val);
        } else if (strcmp(arg, "D") == 0) {
            // DEQ command
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long long val = items[head];
            head = (head + 1) % CAP;
            --count;
            printf("DEQ %lld\n", val);
        } else if (strcmp(arg, "F") == 0) {
            // FRONT command
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long long val = items[head];
            printf("FRONT %lld\n", val);
        } else {
            // Any other input is an error
            puts("ERR");
        }
    }
    return 0;
}
